import{_ as o,l as s,o as e,c as l,v as r,p as n,x as t,d as c,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"CORS","description":"","frontmatter":{"title":"CORS","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cors.md","filePath":"cs/cors.md","lastUpdated":1789023840000}'),p={name:"cs/cors.md"};function A(C,a,S,E,_,m){const i=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="cors" tabindex="-1">CORS <a class="header-anchor" href="#cors" aria-label="Permalink to &quot;CORS&quot;">​</a></h1><div class="epigraph"><p>同源政策默认不让外源脚本读你的响应。CORS 是服务器显式放行的口子：哪个 Origin、是否带凭证。放行过宽等于把 SOP 拆掉。</p><footer>—— W3C CORS；Fetch 标准；对照[同源](/cs/same-origin-csrf)</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/csp">CSP</a>限制本页外连。缺口是<strong>别人的页想读你的 API</strong>。CORS 预检与 Access-Control 头。不给窃取数据的操作步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>SOP 挡读。API 要给合法前端时，反射任意 Origin 且允许凭证会把带 Cookie 的响应给攻击者源。缺口是白名单精确匹配。</p><h3 id="cors-不是-csrf-解" tabindex="-1">CORS 不是 CSRF 解 <a class="header-anchor" href="#cors-不是-csrf-解" aria-label="Permalink to &quot;CORS 不是 CSRF 解&quot;">​</a></h3><p>简单请求仍可跨源发出。CSRF 要 SameSite 或令牌。</p><p><span class="marginnote">Fetch 标准。本课禁止利用错误 CORS 的配方，只要求永不反射不可信 Origin。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分简单请求与预检。凭证模式。对照点击劫持：那是 UI 层，不是读响应。</p>',12)),(e(),n(h,null,{default:t(()=>[d(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ORIGIN%5B%22%E8%AF%B7%E6%B1%82%20Origin%22%5D%20--%3E%20ACL%5B%22%E6%98%AF%E5%90%A6%E5%9C%A8%E7%99%BD%E5%90%8D%E5%8D%95%22%5D%0A%20%20ACL%20--%3E%20READ%5B%22%E5%B8%A6%E5%87%AD%E8%AF%81%E8%AF%BB%E5%93%8D%E5%BA%94%22%5D%0A%20%20ACL%20--%3E%20DENY%5B%22%E6%B5%8F%E8%A7%88%E5%99%A8%E4%B8%8D%E6%8A%8A%E4%BD%93%E4%BA%A4%E7%BB%99%E5%A4%96%E6%BA%90%E8%84%9A%E6%9C%AC%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>保密：跨源读是 C。过宽 CORS 把 API 变成「任何网站都能以用户身份读」。点击劫持下一课是用户在看不见的框里点。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写 PoC 页。点击劫持下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CSP 管本页；CORS 管谁能读本 API。</li><li>反射 Origin 加凭证是拆 SOP。</li><li>CORS 不替代 CSRF 防御。</li><li>下一课点击劫持。</li><li>出处：W3C CORS / Fetch；<a href="/cs/same-origin-csrf">same-origin-csrf</a>。</li></ul>',8))])}const O=o(p,[["render",A]]);export{u as __pageData,O as default};
